SELECT p."assignment_id",p."pekerja_laki_laki",p."pekerja_perempuan",p."jumlah_pekerja",p."memiliki_catatan_keuangan",p."total_pendapatan",p."total_pengeluaran",p."total_aset",p."__key_valid",p."__conflict",WORKER_BAND(p.pekerja_laki_laki,p.pekerja_perempuan,p.jumlah_pekerja,NULL) AS worker_band FROM mart_ub_b p WHERE p.__key_valid=1 AND p.__conflict=0 AND EXISTS (SELECT 1 FROM mart_ub_a u WHERE u.assignment_id=p.assignment_id AND u.status_keberadaan='1. Ditemukan dan masih aktif') AND EXISTS (SELECT 1 FROM mart_assignment_ub a WHERE a.assignment_id=p.assignment_id AND a.status_assignment IN ('APPROVED BY Pengawas','COMPLETED BY Admin Kabupaten'))
